-- 143 — I 5 set asiatici più grandi nel catalogo, letti da Cardmarket (13/11/2026). Seguito della 142.
-- Shiny Star V (S4A), Shiny Treasure ex (SV4A) e le promo giapponesi SM-P, S-P, XY-P hanno più di 300
-- pagine e Cardmarket ne mostra al massimo 300 per elenco: sono stati letti in ordine di numero di
-- collezione dall'inizio e dalla fine (300 + 300) e uniti. Le pagine sono tante quante il totale di
-- Cardmarket: S4A 330, SV4A 360, SM-P 422, S-P 354, XY-P 412.
-- Stesse regole della 142: una riga per pagina (anche le versioni), codice dal nome della carta, set per
-- lingua del gruppo (tutti giapponesi: S4A, SV4A e S-P della 131 prendono le carte; SM-P e XY-P nuovi).
-- Righe nel catalogo: 1878.
-- VA ESEGUITA DOPO sql/142. Rollback: 143_catalogo_asiatici_grandi_ROLLBACK.sql.

begin;

do $$
begin
    if not exists (select 1 from public.set_carte where sigla = 'SV2A@JP') then
        raise exception 'Prima va eseguita sql/142_catalogo_asiatici_mfb.sql';
    end if;
end $$;

create temp table _set_143 (sigla text, esp text, nome text, totale integer, data_uscita date, lingua text) on commit drop;
